mod tests {
    use super::*;
    use std::fs;

    /// A `callisto.toml` that cannot be looked up is not an absent one: its groups and tag templates must not vanish.
    #[test]
    fn a_config_that_cannot_be_looked_up_is_an_error_not_the_default() {
        let tmp = tempfile::tempdir().unwrap();
        let ws = tmp.path().join("ws");
        fs::create_dir(&ws).unwrap();
        fs::write(ws.join("callisto.toml"), "").unwrap();
        let Some(_locked) = callisto_fixtures::locked_dir::LockedDir::lock(&ws) else {
            return;
        };
        assert!(matches!(load(&ws), Err(ConfigError::Read { .. })));
    }

    #[test]
    fn test_config_resolve_rejects_traversal_in_changesets_dir() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let root = tmp.path();
        fs::write(root.join("callisto.toml"), "[changesets]\ndir = \"../../tmp\"\n").expect("write callisto.toml");

        let result = load(root);
        assert!(
            result.is_err(),
        assert!(ConfigError::require_canonical_ecosystem("pypi/pkg-*", "x").is_ok());
        assert!(matches!(
            ConfigError::require_qualified("cargo:pkg", "x"),
            Err(ConfigError::ColonReference { .. })
        ));
    }

    #[test]
    fn test_typo_in_callisto_toml_is_rejected_not_silently_ignored() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let root = tmp.path();
        // "cascade_mode" is a common typo for [cascade] mode = "always"
        fs::write(root.join("callisto.toml"), "[cascade]\ncascade_mode = \"always\"\n").expect("write callisto.toml");

        let result = load(root);
        assert!(
            result.is_err(),
            "load() must reject unknown field 'cascade_mode'; \
             silently ignoring it means the user's typo has no effect and they have no idea why"
        );
    }

    #[test]
    fn test_package_override_publish_to_is_parsed_not_discarded() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let root = tmp.path();
pub fn load(root: &Path) -> Result<ResolvedConfig, ConfigError> {
    let callisto_toml = root.join("callisto.toml");
    let content = callisto_model::strict_fs::read_optional(&callisto_toml).map_err(|e| ConfigError::Read {
        path: callisto_toml.clone(),
        message: e.to_string(),
    })?;
    let raw = if let Some(content) = content {
        toml::from_str::<RawConfig>(&content).map_err(|e| ConfigError::ParseToml {
            path: callisto_toml.clone(),
            message: e.to_string(),
        })?
    } else {
        RawConfig::default()
    };
    resolve(root, raw)
}

