use callisto_model::{CommandRunner, SnapshotReport, PACKAGE_REPORT_SCHEMA_VERSION};

use crate::error::GraphError;
use crate::plan::VersionPlan;
use crate::resolver::DependencyResolver;
use crate::Workspace;

pub fn plan_snapshot<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    tag: &str,
) -> Result<(VersionPlan, SnapshotReport), GraphError> {
    if tag.is_empty() || !tag.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
        return Err(GraphError::SnapshotTagInvalid { tag: tag.to_owned() });
    }
    // Resolve HEAD for real rather than faking it, so unrelated snapshot runs never collide.
    let sha = ws.git_access().head_sha()?;
    let sha_short = sha.short();

    // Label for the report only; each package's actual version is built in its own grammar below.
    let snapshot_tag = format!("0.0.0-{tag}-{sha_short}");
    let base_versions = ws.base_versions()?;
    // No severity cascade to seed here; `ws.tags()` only checks the propagate-failure invariant below.
    ws.tags()?;

    let mut bumps = Vec::new();
    let mut plan_bumps = Vec::new();

    let mut snapshot_versions = std::collections::BTreeMap::new();

    for pkg in ws.graph.packages() {
            "plan_snapshot must propagate a tags-build failure as Err, not silently proceed"
        );
    }

    #[test]
    fn plan_snapshot_rejects_a_tag_that_cannot_be_part_of_a_version() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        git_init_with_commit(root);
        std::fs::create_dir_all(root.join("pkg-a")).unwrap();
        std::fs::write(
            root.join("pkg-a/Cargo.toml"),
            "[package]\nname = \"pkg-a\"\nversion = \"1.0.0\"\n",
        )
        .unwrap();
        let locator = IgnoreWalkLocator::new(root);
        let runner = callisto_fixtures::git::GitRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        for tag in ["", "bad tag", "x/y", "ünï", "a.b"] {
            let error = plan_snapshot(&ws, tag).expect_err(tag);
            assert!(matches!(error, GraphError::SnapshotTagInvalid { .. }), "{tag}: {error}");
        }
        assert!(plan_snapshot(&ws, "pr-42").is_ok());
    }

    /// Plan_snapshot's synthetic snapshot version overwrites every
    /// PlannedBump.to and BumpRecord.to unconditionally, even for members of
    /// a Fixed group -- the cascade-stage target the new Fixed-group
    /// convergence block computes internally is discarded.
    #[test]
use std::fs;
use std::path::Path;
use std::process::ExitCode;

use callisto_graph::GraphError;
use callisto_model::format::{
    parse_pre_json, write_pre_json, write_pre_json_preserving, PreJsonError, PreMode, PreState,
};
use callisto_model::{ApplyPermit, CommandRunner, PreReport, SCHEMA_VERSION};

use crate::cli::{GlobalArgs, OutputFormat, PreArgs};
use crate::error::CliError;
use crate::output::{emit_line, emit_report, log_line};
use crate::runner::CliCommandRunner;
use crate::workspace::load_workspace;

/// Extracted from [`handle`] so a fake [`CommandRunner`] can exercise the `git add` without shelling out for real.
fn stage_pre_json(runner: &dyn CommandRunner, root: &Path, rel_path: &Path) -> Result<(), CliError> {
    let rel_str = rel_path.to_string_lossy();
    let output = runner.run("git", &["add", rel_str.as_ref()], root)?;
    if !output.success() {
        return Err(callisto_model::CommandError::Failed {
            program: "git".to_string(),
            exit_code: output.exit_code,
            stderr: output.redacted_stderr(),
        }
        .into());
    }
    Ok(())
}

/// A baseline that fits no version grammar is a malformed owned baseline (E114), as in `version`; other damage is E212.
/// `pre.json` on disk. Otherwise returns [`CliError::Io`] if reading an existing
/// `pre.json` fails, or if any write fails (`enter` subcommand on a real run).
pub fn handle(args: PreArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let runner = CliCommandRunner;
    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run);

    match args {
        PreArgs::Enter { tag } => {
            // Reject an empty tag before any workspace I/O.
            if tag.trim().is_empty() {
                return Err(CliError::PreTagEmpty);
            }

            let ws = load_workspace(global, &runner)?;

            // Reject re-entering only while a cycle is actually active (mode `pre`); a `pre.json` left
            // behind in `exit` mode is a finished cycle, so entering starts a new one from where it
            // left off instead of erroring on a file that merely still exists on disk.
            let rel_pre_path = ws.config.pre_json_path();
            let pre_path = ws.root.join(&rel_pre_path);
            let pre_dir = pre_path.parent().unwrap_or(&ws.root).to_path_buf();
            let existing_text = callisto_model::strict_fs::read_optional(&pre_path).map_err(|source| CliError::Io {
                source,
                path: Some(pre_path.clone()),
            })?;
            let pre_state = if let Some(existing_text) = existing_text {
                let existing = parse_existing_pre_json(&existing_text)?;
                if existing.mode == PreMode::Pre {
                    return Err(CliError::PreAlreadyActive);
